 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"promotion-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new PricingFixture(new JdbcTemplate(ds),new org.springframework.jdbc.datasource.DataSourceTransactionManager(ds));var clock=Clock.systemUTC();var commands=new PlatformStore(f.jdbc,f.manager,clock,f.metrics);service=new PromotionService(f.jdbc,commands,new PricingAuthority(f.jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),new AuditWriter(f.jdbc,clock,f.metrics),clock,f.metrics,3);prefix="SYNTH_PROMO_"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase();}
